options.css:
:host { color-scheme:dark; }
* { box-sizing:border-box; }
.atlas { width:100%; height:100%; min-height:480px; overflow:auto; container-type:inline-size; color:#eee7de; background:#101016; font:14px Arial,Helvetica,sans-serif; display:flex; flex-direction:column; padding:0 26px; }
header { display:flex; align-items:center; justify-content:space-between; gap:18px; min-height:58px; border-bottom:1px solid #34313b; flex-shrink:0; }
.brand { display:flex; align-items:center; gap:13px; font-weight:700; letter-spacing:.1em; font-size:12px; }
.brand>span { font:38px Georgia,serif; color:#f07c6b; letter-spacing:-.12em; margin-right:5px; }
.brand small { font:9px/1.5 monospace; color:#a6a2ac; border-left:1px solid #34313b; padding-left:15px; }
.badge { font:9px monospace; letter-spacing:.12em; border:1px solid #71644c; color:#e7b976; padding:7px 9px; white-space:nowrap; }
.workspace { display:grid; grid-template-columns:minmax(0,1.6fr) minmax(260px,1fr); gap:34px; flex:1 0 auto; min-height:355px; padding-top:18px; }
.stage { min-height:355px; position:relative; overflow:hidden; border:1px solid #34313b; background:radial-gradient(ellipse at 50% 50%,#22202a55,transparent 66%); }
.stage-top { position:absolute; top:16px; left:18px; right:18px; display:flex; justify-content:space-between; gap:10px; color:#a6a2ac; font:9px monospace; letter-spacing:.1em; z-index:3; }
#heart { position:absolute; left:50%; top:50%; width:min(91%,470px); height:90%; object-fit:contain; transform:translate(-50%,-50%) scale(1); mix-blend-mode:screen; will-change:transform; z-index:1; }
.halo { position:absolute; inset:10% 15%; background:radial-gradient(ellipse,#7f2d3522,transparent 65%); }
.orbit { position:absolute; border:1px solid #96849320; border-radius:50%; width:66%; height:78%; left:17%; top:10%; transform:rotate(-22deg); }
.orbit-two { transform:rotate(24deg); width:83%; left:8%; height:61%; top:20%; }
.annotation { position:absolute; left:18px; top:34%; z-index:2; display:flex; flex-direction:column; gap:8px; max-width:145px; background:linear-gradient(90deg,#101016aa,transparent); padding:6px 0; }
.micro,.eyebrow { font:10px/1.6 monospace; letter-spacing:.12em; color:#a6a2ac; }
.annotation strong { font-size:14px; font-weight:400; }
.annotation>span:last-child { font:10px monospace; color:#a6a2ac; }
.annotation:after { content:''; width:55px; border-bottom:1px solid #7c6471; margin-top:7px; }
.reading { position:absolute; right:20px; bottom:42px; z-index:3; display:grid; grid-template-columns:auto auto; align-items:baseline; gap:0 6px; text-align:right; }
#bpm { font:clamp(52px,6cqw,82px)/1 Georgia,serif; letter-spacing:-.05em; }
.unit { color:#f07c6b; font-size:12px; }
.reading small { grid-column:1/3; margin-top:9px; font:9px monospace; letter-spacing:.1em; color:#a6a2ac; }
.footnote { position:absolute; bottom:12px; left:18px; right:18px; margin:0; color:#a6a2ac; font-size:10px; line-height:1.4; z-index:4; }
aside { padding:0 0 10px; align-self:center; }
.eyebrow { color:#f07c6b; margin:0 0 13px; }
h1 { font:clamp(32px,4cqw,54px)/1.05 Georgia,'Times New Roman',serif; letter-spacing:-.035em; font-weight:400; margin:0 0 17px; }
em { color:#f07c6b; font-weight:400; }
.intro { font-size:13px; line-height:1.65; color:#a6a2ac; margin:0 0 18px; max-width:370px; }
label { display:block; color:#a6a2ac; font-size:11px; }
select { background:#1c1a23; border:1px solid #514a59; color:#eee7de; font:12px Arial,sans-serif; padding:9px 8px; border-radius:0; width:100%; margin-top:7px; }
.facts { display:flex; gap:25px; margin:21px 0; }
.facts>div { flex:1; }
.facts span { display:block; font:9px monospace; letter-spacing:.08em; color:#a6a2ac; margin-bottom:8px; }
.facts strong { font-size:24px; font-weight:400; }
.explanation { border-top:1px solid #34313b; padding-top:12px; }
.explanation p { font-size:11px; line-height:1.6; color:#a6a2ac; margin:5px 0 0; }
.toggles { display:flex; align-items:center; gap:15px; flex-wrap:wrap; margin-top:12px; }
.toggles button { background:none; border:1px solid #514a59; color:#eee7de; padding:7px 9px; font-size:11px; cursor:pointer; }
.gap-label { display:flex; align-items:center; gap:6px; font-size:10px; cursor:pointer; }
input { accent-color:#f07c6b; }
button,select,input { touch-action:manipulation; }
button:focus-visible,input:focus-visible,select:focus-visible { outline:2px solid #e7b976; outline-offset:3px; }
.transport { display:flex; align-items:center; gap:18px; margin-top:14px; padding:12px 0; border-bottom:1px solid #34313b; flex-shrink:0; }
.play { width:42px; height:42px; flex-shrink:0; border-radius:50%; border:0; color:#201519; background:#f07c6b; font-size:17px; cursor:pointer; }
.clock { display:flex; flex-direction:column; gap:4px; min-width:60px; font:10px monospace; color:#a6a2ac; }
.clock strong { font-size:18px; color:#eee7de; font-weight:400; }
.scrubber { flex:1; }
.scrubber label,.speed-label { font:9px monospace; letter-spacing:.08em; }
.scrubber input { width:100%; height:20px; cursor:pointer; }
.scrubber>div { display:flex; justify-content:space-between; font:8px monospace; color:#86818e; }
.speed-label { width:85px; }
.speed-label select { padding:5px; margin-top:5px; }
footer { display:flex; justify-content:space-between; gap:10px; padding:11px 0; color:#a6a2ac; font:8px monospace; letter-spacing:.05em; flex-shrink:0; }
.dimmed #heart { opacity:.28; filter:grayscale(1); }
.reduced .orbit { display:none; }
@container (max-width:760px) { .workspace { gap:20px; grid-template-columns:minmax(0,1.3fr) minmax(225px,1fr); } .brand small { display:none; } h1 { font-size:35px; } .annotation { top:28%; } .stage-top span:last-child { display:none; } .facts { margin:16px 0; } .explanation { display:none; } }
@container (max-width:550px) { .workspace { display:flex; flex-direction:column; flex:0 0 auto; gap:12px; } .stage { min-height:330px; } aside { width:100%; padding:0; } aside>.eyebrow,aside>h1,aside>.intro,.facts,.explanation { display:none; } .toggles { margin-top:8px; } .brand { font-size:10px; } .annotation { top:32%; } footer>span:last-child { display:none; } .transport { gap:10px; } .clock { min-width:48px; } .speed-label { width:62px; } }

options.onInit:
// Native HTML Graphics lifecycle. The artwork and fictional samples are bundled.
if (htmlNode.__atlasCleanup) htmlNode.__atlasCleanup();
const $ = id => htmlNode.getElementById(id);
const root = htmlNode.querySelector('.atlas');
const workouts = htmlGraphics.customProperties.workouts;
const motionPreference = window.matchMedia('(prefers-reduced-motion: reduce)');
const state = {workout:0, time:0, playing:true, reduced:motionPreference.matches, speed:30, gap:false};
let disposed = false;
let raf = 0;
let last = 0;
let lastPaint = 0;
const listeners = [];
function listen(target, name, fn) { target.addEventListener(name,fn); listeners.push(() => target.removeEventListener(name,fn)); }
function clock(seconds) { const s=Math.max(0,Math.floor(seconds||0)); return `${Math.floor(s/60).toString().padStart(2,'0')}:${(s%60).toString().padStart(2,'0')}`; }
function sampleAt(samples, second, maxAge=30) {
  let lo=0, hi=samples.length-1, found=-1;
  while(lo<=hi) { const mid=(lo+hi)>>1; if(samples[mid].t<=second) { found=mid;lo=mid+1; } else hi=mid-1; }
  const sample=found>=0?samples[found]:null;
  return sample && second-sample.t<=maxAge && Number.isFinite(sample.bpm) && sample.bpm>0 ? sample:null;
}
// Same two-part pulse as Living Atlas / dist/core.js.
function beatScale(bpm, time, enabled) {
  if(!enabled || !Number.isFinite(bpm) || bpm<=0) return 1;
  const p=(time*bpm/60)%1;
  return 1+.045*Math.exp(-(((p-.12)/.07)**2))+.019*Math.exp(-(((p-.32)/.08)**2));
}
function currentSample() { return state.gap?null:sampleAt(workouts[state.workout].hr,state.time); }
function setPlaying(playing) { state.playing=playing; $('play').textContent=playing?'Ⅱ':'▶'; $('play').setAttribute('aria-label',playing?'Pause replay':'Play replay'); }
function setReduced(reduced) { state.reduced=reduced; root.classList.toggle('reduced',reduced); $('motion').setAttribute('aria-pressed',String(reduced)); $('motion').textContent=reduced?'Motion reduced':'Reduce motion'; }
function update() {
  const workout=workouts[state.workout], sample=currentSample();
  $('bpm').textContent=sample?Math.round(sample.bpm):'—';
  $('signal').textContent=sample?'Signal available':'No recent sample';
  $('age').textContent=sample?`${Math.round(state.time-sample.t)}s since sample`:'No rate is invented';
  root.classList.toggle('dimmed',!sample);
  $('clock').textContent=clock(state.time);
  $('seek').value=String(state.time);
  $('total').textContent='/ '+clock(workout.duration);
  $('duration').textContent=clock(workout.duration);
  $('distance').textContent=Number.isFinite(workout.distance)?`${workout.distance.toFixed(1)} km`:'—';
}
workouts.forEach((w,i) => {
  const option=document.createElement('option'); option.value=String(i); option.textContent=`${w.date} · ${w.activity} · ${w.distance.toFixed(1)} km`; $('workout').appendChild(option);
});
$('seek').max=String(workouts[0].duration);
listen($('workout'),'change',event => { state.workout=Number(event.target.value); state.time=0; state.gap=false; $('gap').checked=false; $('seek').max=String(workouts[state.workout].duration); update(); });
listen($('play'),'click',() => setPlaying(!state.playing));
listen($('seek'),'input',event => { state.time=Number(event.target.value); update(); });
listen($('speed'),'change',event => { state.speed=Number(event.target.value); });
listen($('motion'),'click',() => setReduced(!state.reduced));
listen($('gap'),'change',event => { state.gap=event.target.checked; update(); });
listen(motionPreference,'change',event => setReduced(event.matches));
listen(document,'visibilitychange',() => { last=0; });
function tick(t) {
  if(disposed) return;
  const dt=last?Math.min((t-last)/1000,.2):0; last=t;
  if(state.playing) {
    state.time+=dt*state.speed;
    if(state.time>workouts[state.workout].duration) state.time=0;
  }
  if(t-lastPaint>100) { update(); lastPaint=t; }
  $('heart').style.transform=`translate(-50%,-50%) scale(${beatScale(currentSample()?.bpm,t/1000,state.playing&&!state.reduced)})`;
  raf=requestAnimationFrame(tick);
}
function cleanup() {
  if(disposed) return; disposed=true; cancelAnimationFrame(raf); listeners.forEach(remove => remove());
  htmlNode.removeEventListener('panelwillunmount',cleanup);
  if(htmlNode.__atlasCleanup===cleanup) delete htmlNode.__atlasCleanup;
}
htmlNode.__atlasCleanup=cleanup;
htmlNode.addEventListener('panelwillunmount',cleanup);
setReduced(state.reduced); setPlaying(true); update(); raf=requestAnimationFrame(tick);
